<span class="line"><span style="color:#ABB2BF;">d2l.</span><span style="color:#61AFEF;">show_heatmaps</span><span style="color:#ABB2BF;">(d2l.</span><span style="color:#61AFEF;">reshape</span><span style="color:#ABB2BF;">(attention.attention_weights, (</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">)),</span></span>
